using BijliGuard.Application.Billing;

namespace BijliGuard.Infrastructure.Storage;

/// <summary>
/// Stores bill files in a folder outside the web root, so they are never served as static files.
/// Callers reach them only through an authenticated endpoint. Keys are generated by the server.
/// </summary>
public sealed class LocalFileStorage(string rootPath) : IFileStorage
{
    private readonly string _root = Path.GetFullPath(rootPath);

    public async Task SaveAsync(string key, byte[] content, CancellationToken ct)
    {
        var path = PathFor(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        await File.WriteAllBytesAsync(path, content, ct);
    }

    public Task<Stream> OpenReadAsync(string key, CancellationToken ct)
    {
        var path = PathFor(key);
        Stream stream = File.OpenRead(path);
        return Task.FromResult(stream);
    }

    private string PathFor(string key)
    {
        // Defence in depth: the key comes from our own generator, but reject anything that is not a plain file name.
        if (key.Length == 0 || key.Any(c => !char.IsLetterOrDigit(c) && c != '.'))
            throw new ArgumentException("Invalid storage key.", nameof(key));

        var path = Path.GetFullPath(Path.Combine(_root, key));
        if (!path.StartsWith(_root, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("Storage path escaped the root folder.");
        return path;
    }
}
